applied_count = 0
for idx, enrich in batch4_enrichments.items():
    if idx < len(questions):
        q = questions[idx]
        # Verify original stem and options are NOT modified
        orig_q = q["question_fa"]
        orig_opts = list(q["options_fa"])
        
        # Apply clinical enrichment
        q["subject_fa"] = enrich["subject_fa"]
        q["chapter_fa"] = enrich["chapter_fa"]
        q["correct_index"] = enrich["correct_index"]
        q["explanation_fa"] = enrich["explanation_fa"]
        q["options_why_fa"] = enrich["options_why_fa"]
        
        # Micro structure
        if "micro" not in q or not isinstance(q["micro"], dict):
            q["micro"] = {}
        q["micro"]["lead_fa"] = enrich["micro"]["lead_fa"]
        q["micro"]["golden_fa"] = enrich["micro"]["golden_fa"]
        q["micro"]["points_fa"] = enrich["micro"]["points_fa"]
        
        # Verify stem and options remained identical
        assert q["question_fa"] == orig_q
        assert q["options_fa"] == orig_opts
        assert len(q["options_why_fa"]) == 4
        assert len(q["micro"]["points_fa"]) == 4
        assert 0 <= q["correct_index"] < len(q["options_fa"])
        
        applied_count += 1

print(f"Applied Batch 4 enrichment to {applied_count} questions.")

